<?php
namespace App\Http\Controllers;
use App\Models\AiModelExperiment;use App\Models\AiProductAnalysis;use App\Models\AiRuntimeLog;use App\Models\Product;use App\Models\ProductReview;use App\Services\AI\AIManager;use Illuminate\View\View;
class AdminAiDashboardController{public function index(AIManager $ai):View{$stats=['pending'=>Product::whereIn('ai_status',['not_checked','pending','pending_review','pending_ai','ready_for_review'])->count(),'approved'=>Product::where('ai_status','approved')->count(),'flagged'=>Product::whereIn('ai_status',['blocked','needs_revision'])->count(),'reviews'=>ProductReview::where('is_published',true)->count()];$recent=AiProductAnalysis::with('product')->latest()->take(12)->get();$logs=AiRuntimeLog::latest()->take(12)->get();$experiments=AiModelExperiment::orderByDesc('enabled')->orderByDesc('id')->take(8)->get();return view('admin.ai.dashboard',compact('stats','recent','logs','experiments','ai'));}}